3	export async function total_amount_matches_events(ctx: AssertionContext): Promise<AssertionResult> {
4	  const result = await ctx.pg.query(
5	    "SELECT coalesce(sum(total_amount), 0) AS s FROM app.order_snapshots WHERE status = 'active'",
6	  );
7	  const snapshotSum = Number(result.rows[0]?.s ?? 0);
8	  const expectedSum = 20.0 + 14.25 + 99.0;
9	  const passed = Math.abs(snapshotSum - expectedSum) < 0.01;
10	  return {
11	    passed,
12	    message: passed ? "Total amount matches replayed events." : `Expected ~${expectedSum}, got ${snapshotSum}.`,
13	    details: { snapshotSum, expectedSum },
14	  };
15	}
