17	export async function cancelled_order_has_zero_amount(ctx: AssertionContext): Promise<AssertionResult> {
18	  const result = await ctx.pg.query(
19	    "SELECT total_amount FROM app.order_snapshots WHERE order_id = 'ord_002' AND status = 'cancelled'",
20	  );
21	  const passed = result.rows.length === 1 && Number(result.rows[0]?.total_amount ?? -1) === 0;
22	  return {
23	    passed,
24	    message: passed ? "Cancelled order has zero amount." : "ord_002 should be cancelled with amount 0.",
25	    details: { rows: result.rows.length },
26	  };
27	}
